'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),DB=require('../server/database-connection.cjs');
const root=path.resolve(__dirname,'..'),digest=s=>crypto.createHash('sha256').update(s).digest('hex');
// This release baseline is reviewed and versioned, never regenerated by a migration command.
function load({directory=path.join(root,'db/migrations'),baselineFile=path.join(root,'db/migration-baseline.json')}={}){
 const baseline=JSON.parse(fs.readFileSync(baselineFile,'utf8')),entries=baseline.migrations;
 if(baseline.format!==1||!Array.isArray(entries)||!entries.length||entries.some((e,i)=>!/^\d{3}[a-z]?_[a-z0-9_]+\.sql$/.test(e.version)||!/^([a-f0-9]{64})$/.test(e.checksum)||i>0&&entries[i-1].version>=e.version))DB.fail('MIGRATION_BASELINE_INVALID');
 if(entries.at(-1).version!==require('../server/release.cjs').requiredMigration)DB.fail('MIGRATION_RELEASE_BASELINE_MISMATCH');
 const files=fs.readdirSync(directory).filter(f=>f.endsWith('.sql')).sort();
 if(files.length!==entries.length||files.some((f,i)=>f!==entries[i].version))DB.fail('MIGRATION_CHAIN_UNEXPECTED');
 return entries.map(e=>{const sql=fs.readFileSync(path.join(directory,e.version),'utf8');if(digest(sql)!==e.checksum)DB.fail('MIGRATION_SOURCE_CHECKSUM_CHANGED');return {...e,sql};});
}
function applied(rows,chain,{complete=false}={}){
 const known=new Map(chain.map(e=>[e.version,e])),seen=new Map();
 for(const r of rows){if(!known.has(r.version)||seen.has(r.version))DB.fail('MIGRATION_DATABASE_VERSION_UNKNOWN');if(known.get(r.version).checksum!==r.checksum)DB.fail('MIGRATION_CHECKSUM_CHANGED');seen.set(r.version,r);}
 let gap=false;for(const e of chain){if(!seen.has(e.version))gap=true;else if(gap)DB.fail('MIGRATION_DATABASE_HISTORY_GAP');}
 if(complete&&seen.size!==chain.length)DB.fail('MIGRATION_DATABASE_INCOMPLETE');
 return seen;
}
async function guard172(client,stage){
 if(!['before','after'].includes(stage))DB.fail('MIGRATION_GUARD_STAGE_INVALID');
 const spec=JSON.parse(fs.readFileSync(path.join(root,'db/migration-guards/172-admin-permissions.json'),'utf8'));
 const actual=(await client.query("SELECT p.oid::regprocedure::text signature,p.prosrc body,p.prosecdef security_definer,p.proconfig configuration FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=ANY($1) ORDER BY p.oid::regprocedure::text",[spec.names])).rows;
 const managerSubmission=stage==='after'&&(await client.query("SELECT EXISTS(SELECT 1 FROM schema_migrations WHERE version='176_v470_map_and_workflows.sql') applied")).rows[0].applied;
 if(managerSubmission){
  for(const r of actual.filter(r=>/^(ux10_plan_submission|v468_submit_legacy_plan_edit)\(/.test(r.signature))){
   const expanded="u.role_code IN('sales_operator','admin','sales_manager')";
   if(!r.body.includes(expanded))DB.fail('MIGRATION_176_SALES_FUNCTION_MISMATCH');
   r.body=r.body.replaceAll(expanded,"u.role_code IN('sales_operator','admin')");
  }
 }
 const expected=new Map(spec[stage].map(r=>[r.signature,r]));
 if(actual.length!==expected.size||actual.some(r=>{const e=expected.get(r.signature);return !e||digest(r.body)!==e.bodySha256||r.security_definer!==e.security_definer||JSON.stringify(r.configuration)!==JSON.stringify(e.configuration);}))DB.fail('MIGRATION_172_FUNCTION_BASELINE_MISMATCH');
}
async function execute(client,entry){
 const guarded=entry.version==='172_v469_configurable_admin_business_permissions.sql';
 if(guarded)await guard172(client,'before');
 await client.query(entry.sql);
 if(guarded)await guard172(client,'after');
 await client.query('INSERT INTO schema_migrations(version,checksum) VALUES($1,$2)',[entry.version,entry.checksum]);
}
module.exports={load,applied,guard172,execute,digest};
